function withQuery(path: string, query: Record<string, string | number | boolean>): string {
  const params = new URLSearchParams();
  Object.entries(query).forEach(([key, value]) => {
    params.set(key, String(value));
  });
  const qs = params.toString();
  return qs ? `${path}?${qs}` : path;
}

export async function listHdaInvoices(
  query: Record<string, string | number | boolean>,
): Promise<HdaInvoiceListItem[]> {
  const res = await apiClient.get<BffResponse<HdaInvoiceListItem[]>>(withQuery(BASE, query));
  return unwrap(res);
}

export async function getHdaInvoice(sttRec: string): Promise<HdaInvoice> {
  const res = await apiClient.get<BffResponse<HdaInvoice>>(`${BASE}/${encodeURIComponent(sttRec)}`);
  return unwrap(res);
}

export async function createHdaInvoice(body: HdaInvoiceWrite): Promise<HdaInvoice> {
  const res = await apiClient.post<BffResponse<HdaInvoice>>(BASE, body);
  return unwrap(res);
}

export async function updateHdaInvoice(sttRec: string, body: HdaInvoiceWrite): Promise<HdaInvoice> {
  const res = await apiClient.put<BffResponse<HdaInvoice>>(`${BASE}/${encodeURIComponent(sttRec)}`, body);
  return unwrap(res);
}
