function lineFromApi(line: HdaInvoice['lines'][number], copy: boolean): LineState {
  return {
    sttRec0: copy ? '' : line.sttRec0,
    maVt: line.maVt ?? '',
    tenVt: line.tenVt ?? '',
    dvt: line.dvt ?? '',
    maVitri: line.maVitri ?? '',
    maKhoI: line.maKhoI ?? '',
    ton13: copy ? '0' : moneyText(line.ton13),
    soLuong: moneyText(line.soLuong),
    giaNt2: moneyText(line.giaNt2),
    tienNt2: moneyText(line.tienNt2),
    ptCk: moneyText(line.ptCk),
    ckNt: moneyText(line.ckNt),
    ck: moneyText(line.ck),
    tkCk: line.tkCk ?? '',
    tkDt: line.tkDt ?? '',
    giaNt: copy ? '0' : moneyText(line.giaNt),
    tienNt: copy ? '0' : moneyText(line.tienNt),
    gia: copy ? '0' : moneyText(line.gia),
    tkVt: line.tkVt ?? '',
    tkGv: line.tkGv ?? '',
    maVvI: line.maVvI ?? '',
    maHdI: line.maHdI ?? '',
    maPhiI: line.maPhiI ?? '',
    maTtlnI: line.maTtlnI ?? '',
    maTtcpI: line.maTtcpI ?? '',
    maBpI: line.maBpI ?? '',
    tien: copy ? 0 : line.tien ?? 0,
  };
}

function formFromApi(dto: HdaInvoice, copy: boolean): FormState {
  return {
    maGd: dto.maGd || '1',
    maPost: dto.maPost || '3',
    loaiHd: dto.loaiHd ?? '',
    maQuyen: dto.maQuyen ?? '',
    ngayCt: dateText(dto.ngayCt) || today(),
    ngayLct: dateText(dto.ngayLct) || today(),
    soCt: dto.soCt ?? '',
    mauHd: dto.mauHd ?? '',
    mauSo: dto.mauSo ?? '',
    soSeri: dto.soSeri ?? '',
    soLo: dto.soLo ?? '',
    ngayLo: dateText(dto.ngayLo),
    maKh: dto.maKh ?? '',
    tenKh: dto.tenKh ?? '',
    ongBa: dto.ongBa ?? '',
    diaChi: dto.diaChi ?? '',
    maSoThue: dto.maSoThue ?? '',
    dienGiai: dto.dienGiai ?? '',
    maBpH: dto.maBpH ?? '',
    maHsH: dto.maHsH ?? '',
    maNx: dto.maNx ?? '',
    pxGiaDd: dto.pxGiaDd === 1,
    maNt: dto.maNt ?? '',
    tyGia: moneyText(dto.tyGia),
    maThue: dto.maThue ?? '',
    thueSuat: moneyText(dto.thueSuat),
    tkThueCo: dto.tkThueCo ?? '',
    tkThueNo: dto.tkThueNo ?? '',
    suaCk: dto.suaCk === 1,
    suaTkThue: dto.suaTkThue === 1,
    suaThue: dto.suaThue === 1,
    suaThueCk: dto.suaThueCk === 1,
    hanTt: moneyText(dto.hanTt),
    htTt: dto.htTt ?? '',
    tenVtThue: dto.tenVtThue ?? '',
    tenKhVat: dto.tenKhVat ?? '',
    diaChiVat: dto.diaChiVat ?? '',
    tThueNt: moneyText(dto.tThueNt),
    tThue: moneyText(dto.tThue),
    lines: (dto.lines ?? []).map(line => lineFromApi(line, copy)),
  };
}

function blockMessage(form: FormState): string {
  if (!form.maKh.trim()) return 'Bạn chưa nhập khách hàng mua xe';
  if (form.lines.length === 0) return '';
  if (!form.tkThueCo.trim()) return 'Bạn chưa nhập tài khoản thuế';
  if (!form.maNx.trim()) return 'Bạn chưa nhập tài khoản ghi nợ';
  for (const line of form.lines) {
    if (!line.maKhoI.trim()) return 'Bạn chưa nhập kho xuất';
    if (!line.tkVt.trim()) return 'Bạn chưa nhập tài khoản hàng hóa';
    if (!line.tkGv.trim()) return 'Bạn chưa nhập tài khoản gía vốn';
    if (!line.tkDt.trim()) return 'Bạn chưa nhập tài khoản doanh thu';
    const ckNt = num(line.ckNt);
    if (ckNt !== null && ckNt !== 0 && !line.tkCk.trim()) return 'Bạn chưa nhập tài khoản chiết khấu';
  }
  return '';
}

function toWrite(form: FormState, copy: boolean): HdaInvoiceWrite {
  const lines: HdaInvoiceWriteLine[] = form.lines.map(line => {
    const row: HdaInvoiceWriteLine = {
      maVt: textOrNull(line.maVt),
      tenVt: textOrNull(line.tenVt),
      dvt: textOrNull(line.dvt),
      maVitri: textOrNull(line.maVitri),
      maKhoI: textOrNull(line.maKhoI),
      ton13: copy || !line.sttRec0 ? 0 : num(line.ton13) ?? 0,
      soLuong: num(line.soLuong),
      giaNt2: num(line.giaNt2),
      tienNt2: num(line.tienNt2),
      ptCk: num(line.ptCk),
      ckNt: num(line.ckNt),
      ck: num(line.ck),
      tkCk: textOrNull(line.tkCk),
      tkDt: textOrNull(line.tkDt),
      giaNt: copy || !line.sttRec0 ? 0 : num(line.giaNt) ?? 0,
      tienNt: copy || !line.sttRec0 ? 0 : num(line.tienNt) ?? 0,
      gia: copy || !line.sttRec0 ? 0 : num(line.gia) ?? 0,
      tkVt: textOrNull(line.tkVt),
      tkGv: textOrNull(line.tkGv),
      maVvI: textOrNull(line.maVvI),
      maHdI: textOrNull(line.maHdI),
      maPhiI: textOrNull(line.maPhiI),
      maTtlnI: textOrNull(line.maTtlnI),
      maTtcpI: textOrNull(line.maTtcpI),
      maBpI: textOrNull(line.maBpI),
    };
    if (!copy && line.sttRec0) row.sttRec0 = line.sttRec0;
    return row;
  });
  return {
    maCt: 'HDA',
    maGd: form.maGd,
    maPost: form.maPost,
    loaiHd: textOrNull(form.loaiHd),
    maQuyen: textOrNull(form.maQuyen),
    ngayCt: textOrNull(form.ngayCt),
    ngayLct: textOrNull(form.ngayLct),
    soCt: textOrNull(form.soCt),
    mauHd: textOrNull(form.mauHd),
    mauSo: textOrNull(form.mauSo),
    soSeri: textOrNull(form.soSeri),
    soLo: textOrNull(form.soLo),
    ngayLo: textOrNull(form.ngayLo),
    maKh: textOrNull(form.maKh),
    ongBa: textOrNull(form.ongBa),
    diaChi: textOrNull(form.diaChi),
    maSoThue: textOrNull(form.maSoThue),
    dienGiai: textOrNull(form.dienGiai),
    maBpH: textOrNull(form.maBpH),
    maHsH: textOrNull(form.maHsH),
    maNx: textOrNull(form.maNx),
    pxGiaDd: form.pxGiaDd ? 1 : 0,
    maNt: textOrNull(form.maNt),
    tyGia: num(form.tyGia),
    maThue: textOrNull(form.maThue),
    thueSuat: num(form.thueSuat),
    tkThueCo: textOrNull(form.tkThueCo),
    tkThueNo: textOrNull(form.tkThueNo),
    suaCk: form.suaCk ? 1 : 0,
    suaTkThue: form.suaTkThue ? 1 : 0,
    suaThue: form.suaThue ? 1 : 0,
    suaThueCk: form.suaThueCk ? 1 : 0,
    hanTt: num(form.hanTt),
    htTt: textOrNull(form.htTt),
    tenVtThue: textOrNull(form.tenVtThue),
    tenKhVat: textOrNull(form.tenKhVat),
    diaChiVat: textOrNull(form.diaChiVat),
    tThueNt: num(form.tThueNt),
    tThue: num(form.tThue),
    lines,
  };
}

const HdaFormPage: React.FC = () => {
  const { sttRec } = useParams();
  const [params] = useSearchParams();
  const copyFrom = params.get('copyFrom') ?? '';
  const isView = params.get('mode') === 'view';
  const isNew = !sttRec;
  const isCopy = isNew && !!copyFrom;
  const navigate = useInAppNavigate();
  const dispatch = useAppDispatch();
  const { onDirtyChange, guardedNavigate, leaveConfirmModalProps } = useFormLeaveGuard({ message: LEAVE_MESSAGE });
  const { markDirty, markClean } = useDirtyTracking(isView ? undefined : onDirtyChange);
  const [form, setForm] = useState<FormState>(emptyForm);
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const [missing, setMissing] = useState(false);
  const [selectedLine, setSelectedLine] = useState(-1);

  useEffect(() => {
    const id = sttRec || copyFrom;
    if (!id) {
      setForm(emptyForm());
      setMissing(false);
      markClean();
      return;
    }
    let cancelled = false;
    setLoading(true);
    setError('');
    setMissing(false);
    getHdaInvoice(id)
      .then(dto => {
        if (cancelled) return;
        setForm(formFromApi(dto, isCopy));
        markClean();
      })
      .catch(err => {
        if (cancelled) return;
        setMissing(true);
        setError(getApiErrorMessage(err, 'Không tìm thấy hoá đơn bán hàng'));
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [sttRec, copyFrom, isCopy]);

  const touch = (next: FormState) => {
    setForm(next);
    if (!isView) markDirty();
  };

  const setField = (key: keyof FormState, value: string | boolean) => {
    touch({ ...form, [key]: value });
  };

  const setLine = (index: number, patch: Partial<LineState>) => {
    const lines = form.lines.map((line, i) => (i === index ? { ...line, ...patch } : line));
    const current = lines[index];
    if (patch.soLuong !== undefined || patch.giaNt2 !== undefined) {
      if (!current.tienNt2.trim() && num(current.soLuong) !== null && num(current.giaNt2) !== null) {
        current.tienNt2 = String(round4((num(current.soLuong) ?? 0) * (num(current.giaNt2) ?? 0)));
      }
    }
    if (patch.ptCk !== undefined || patch.tienNt2 !== undefined) {
      if (!form.lines[index].ckNt.trim() && num(current.ptCk) !== null && num(current.tienNt2) !== null) {
        current.ckNt = String(round4((num(current.tienNt2) ?? 0) * (num(current.ptCk) ?? 0) / 100));
      }
    }
    if ((patch.ckNt !== undefined || patch.ptCk !== undefined) && !form.lines[index].ck.trim()) {
      const ty = num(form.tyGia) ?? 0;
      const ckNt = num(current.ckNt);
      current.ck = ckNt === null ? current.ck : ty === 0 ? '0' : String(round4(ckNt * ty));
    }
    touch({ ...form, lines });
  };

  const totals = useMemo(() => {
    const ty = num(form.tyGia) ?? 0;
    let tSoLuong = 0;
    let tTienNt2 = 0;
    let tTien2 = 0;
    let tCkNt = 0;
    let tCk = 0;
    let tTienNt = 0;
    let tTien = 0;
    form.lines.forEach(line => {
      const soLuong = num(line.soLuong) ?? 0;
      const giaNt2 = num(line.giaNt2);
      const tienNt2 = line.tienNt2.trim()
        ? num(line.tienNt2) ?? 0
        : giaNt2 !== null && line.soLuong.trim()
          ? round4(soLuong * giaNt2)
          : 0;
      const ckNt = line.ckNt.trim()
        ? num(line.ckNt) ?? 0
        : line.ptCk.trim() && (line.tienNt2.trim() || (line.soLuong.trim() && line.giaNt2.trim()))
          ? round4(tienNt2 * (num(line.ptCk) ?? 0) / 100)
          : 0;
      const ck = line.ck.trim() ? num(line.ck) ?? 0 : ty === 0 ? 0 : round4(ckNt * ty);
      const tien2 = ty === 0 ? 0 : round4(tienNt2 * ty);
      tSoLuong += soLuong;
      tTienNt2 += tienNt2;
      tTien2 += tien2;
      tCkNt += ckNt;
      tCk += ck;
      tTienNt += num(line.tienNt) ?? 0;
      tTien += line.tien ?? 0;
    });
    const tThueNt = num(form.tThueNt) ?? 0;
    const tThue = num(form.tThue) ?? 0;
    return {
      tSoLuong: round4(tSoLuong),
      tTienNt2: round4(tTienNt2),
      tTien2: round4(tTien2),
      tCkNt: round4(tCkNt),
      tCk: round4(tCk),
      tTienNt: round4(tTienNt),
      tTien: round4(tTien),
      tTtNt: round4(tTienNt2 - tCkNt + tThueNt),
      tTt: round4(tTien2 - tCk + tThue),
    };
  }, [form]);

  const onBlurCustomer = async () => {
    const code = form.maKh.trim();
    if (!code) {
      setForm(prev => ({ ...prev, tenKh: '' }));
      return;
    }
    try {
      const res = await ktService.searchCustomers({ search: code, page: 1, pageSize: 20, isActive: true });
      const hit = res.items.find(item => item.code.trim().toLowerCase() === code.toLowerCase());
      setForm(prev => ({ ...prev, tenKh: hit?.name ?? '' }));
    } catch {
      /* tra cứu không chặn gõ */
    }
  };

  const onBlurMaterial = async (index: number) => {
    const code = form.lines[index]?.maVt.trim() ?? '';
    if (!code) {
      setLine(index, { tenVt: '', dvt: '' });
      return;
    }
    try {
      const res = await ktService.searchMaterials({ search: code, page: 1, pageSize: 20 });
      const hit = res.items.find(item => item.code.trim().toLowerCase() === code.toLowerCase());
      setForm(prev => {
        const lines = prev.lines.map((line, i) => i === index
          ? { ...line, tenVt: hit?.name ?? '', dvt: hit?.unitCode ?? '' }
          : line);
        return { ...prev, lines };
      });
    } catch {
      /* tra cứu không chặn gõ */
    }
  };

  const onSave = async () => {
    const blocked = blockMessage(form);
    if (blocked) {
      setError(blocked);
      dispatchAppToast(dispatch, { type: 'error', message: blocked });
      return;
    }
    setSaving(true);
    setError('');
    try {
      const body = toWrite(form, isCopy);
      const saved = isNew
        ? await createHdaInvoice(body)
        : await updateHdaInvoice(sttRec ?? '', body);
      markClean();
      dispatchAppToast(dispatch, { type: 'success', message: 'Đã lưu hoá đơn bán hàng' });
      if (isNew) navigate(`/kt/hda/${saved.sttRec}`);
      else {
        setForm(formFromApi(saved, false));
        markClean();
      }
    } catch (err) {
      const message = getApiErrorMessage(err, 'Lưu thất bại');
      setError(message);
      dispatchAppToast(dispatch, { type: 'error', message });
    } finally {
      setSaving(false);
    }
  };

  const readOnly = isView;
  const title = isView ? 'Xem hoá đơn bán hàng' : isNew ? 'Thêm hoá đơn bán hàng' : 'Sửa hoá đơn bán hàng';

  const lineMoney = (line: LineState, key: 'gia2' | 'tien2') => {
    const ty = num(form.tyGia) ?? 0;
    if (key === 'gia2') {
      const gia = num(line.giaNt2);
      return gia === null || ty === 0 ? 0 : round4(gia * ty);
    }
    const tien = line.tienNt2.trim()
      ? num(line.tienNt2) ?? 0
      : num(line.soLuong) !== null && num(line.giaNt2) !== null
        ? round4((num(line.soLuong) ?? 0) * (num(line.giaNt2) ?? 0))
        : 0;
    return ty === 0 ? 0 : round4(tien * ty);
  };

  return (
    <div className={df.page} data-testid="ct-hda-form">
      <DocumentFormHeader
        title={title}
        isNew={isNew}
        isReadOnly={readOnly}
        saving={saving}
        testIdPrefix="ct-hda"
        saveLabel="Lưu"
        saveEditLabel="Lưu"
        onBack={() => guardedNavigate(() => navigate('/kt/hda'))}
        onSave={missing || readOnly ? undefined : () => { void onSave(); }}
      />
      <LeaveConfirmModal {...leaveConfirmModalProps} />
      {error ? <div className={df.errorBanner}>{error}</div> : null}
      {loading ? <div className={df.loading}>Đang tải...</div> : null}
      {!missing && !loading ? (
        <>
          <section className={df.section}>
            <h2 className={df.sectionTitle}>Chứng từ</h2>
            <div className={df.row4}>
              <Select label="Loại giao dịch" data-testid="ct-hda-field-maGd" disabled={readOnly} value={form.maGd} options={[{ value: '1', label: 'Xuất bán' }, { value: '2', label: 'Xuất bán nội bộ' }]} onChange={event => setField('maGd', event.target.value)} />
              <Select label="Trạng thái" data-testid="ct-hda-field-maPost" disabled={readOnly} value={form.maPost} options={[{ value: '3', label: 'Lập hoá đơn' }, { value: '9', label: 'Hạch toán sổ cái' }]} onChange={event => setField('maPost', event.target.value)} />
              <div><label className={df.label}>Loại hóa đơn</label><Input maxLength={1} disabled={readOnly} data-testid="ct-hda-field-loaiHd" value={form.loaiHd} onChange={event => setField('loaiHd', event.target.value)} /></div>
              <div><label className={df.label}>Quyền số</label><Input maxLength={30} disabled={readOnly} data-testid="ct-hda-field-maQuyen" value={form.maQuyen} onChange={event => setField('maQuyen', event.target.value)} /></div>
              <div><label className={df.label}>Ngày C.từ</label><Input type="date" disabled={readOnly} data-testid="ct-hda-field-ngayCt" value={form.ngayCt} onChange={event => setField('ngayCt', event.target.value)} /></div>
              <div><label className={df.label}>Ngày lập</label><Input type="date" disabled={readOnly} data-testid="ct-hda-field-ngayLct" value={form.ngayLct} onChange={event => setField('ngayLct', event.target.value)} /></div>
              <div><label className={df.label}>Số C.từ</label><Input maxLength={30} disabled={readOnly} data-testid="ct-hda-field-soCt" value={form.soCt} onChange={event => setField('soCt', event.target.value)} /></div>
              <div><label className={df.label}>Mẫu HĐ</label><Input maxLength={30} disabled={readOnly} data-testid="ct-hda-field-mauHd" value={form.mauHd} onChange={event => setField('mauHd', event.target.value)} /></div>
              <div><label className={df.label}>Mẫu số</label><Input maxLength={30} disabled={readOnly} data-testid="ct-hda-field-mauSo" value={form.mauSo} onChange={event => setField('mauSo', event.target.value)} /></div>
              <div><label className={df.label}>Số seri</label><Input maxLength={30} disabled={readOnly} data-testid="ct-hda-field-soSeri" value={form.soSeri} onChange={event => setField('soSeri', event.target.value)} /></div>
              <div><label className={df.label}>Số lô</label><Input maxLength={30} disabled={readOnly} data-testid="ct-hda-field-soLo" value={form.soLo} onChange={event => setField('soLo', event.target.value)} /></div>
              <div><label className={df.label}>Ngày lô</label><Input type="date" disabled={readOnly} data-testid="ct-hda-field-ngayLo" value={form.ngayLo} onChange={event => setField('ngayLo', event.target.value)} /></div>
            </div>
          </section>
          <section className={df.section}>
            <h2 className={df.sectionTitle}>Đối tượng</h2>
            <div className={df.row4}>
              <div><label className={df.label}>Khách hàng</label><Input maxLength={30} disabled={readOnly} data-testid="ct-hda-field-maKh" value={form.maKh} onChange={event => setField('maKh', event.target.value)} onBlur={() => { void onBlurCustomer(); }} /></div>
              <div><label className={df.label}>Tên đối tượng</label><Input disabled data-testid="ct-hda-field-tenKh" value={form.tenKh} /></div>
              <div><label className={df.label}>Người mua</label><Input maxLength={200} disabled={readOnly} data-testid="ct-hda-field-ongBa" value={form.ongBa} onChange={event => setField('ongBa', event.target.value)} /></div>
              <div className={df.spanCol2}><label className={df.label}>Địa chỉ</label><Input maxLength={200} disabled={readOnly} data-testid="ct-hda-field-diaChi" value={form.diaChi} onChange={event => setField('diaChi', event.target.value)} /></div>
              <div><label className={df.label}>Mã số thuế</label><Input maxLength={30} disabled={readOnly} data-testid="ct-hda-field-maSoThue" value={form.maSoThue} onChange={event => setField('maSoThue', event.target.value)} /></div>
              <div className={df.spanCol2}><label className={df.label}>Diễn giải</label><Input maxLength={200} disabled={readOnly} data-testid="ct-hda-field-dienGiai" value={form.dienGiai} onChange={event => setField('dienGiai', event.target.value)} /></div>
              <div><label className={df.label}>Bộ phận</label><Input maxLength={30} disabled={readOnly} data-testid="ct-hda-field-maBpH" value={form.maBpH} onChange={event => setField('maBpH', event.target.value)} /></div>
              <div><label className={df.label}>Hồ sơ</label><Input maxLength={30} disabled={readOnly} data-testid="ct-hda-field-maHsH" value={form.maHsH} onChange={event => setField('maHsH', event.target.value)} /></div>
            </div>
          </section>
          <section className={df.section}>
            <h2 className={df.sectionTitle}>Tài khoản và tiền tệ</h2>
            <div className={df.row4}>
              <div><label className={df.label}>Tài khoản ghi nợ</label><Input maxLength={30} disabled={readOnly} data-testid="ct-hda-field-maNx" value={form.maNx} onChange={event => setField('maNx', event.target.value)} /></div>
              <Checkbox label="Giá đích danh" disabled={readOnly} data-testid="ct-hda-field-pxGiaDd" checked={form.pxGiaDd} onChange={event => setField('pxGiaDd', event.target.checked)} />
              <div><label className={df.label}>Ngoại tệ</label><Input maxLength={3} disabled={readOnly} data-testid="ct-hda-field-maNt" value={form.maNt} onChange={event => setField('maNt', event.target.value)} /></div>
              <div><label className={df.label}>Tỷ giá</label><Input inputMode="decimal" disabled={readOnly} data-testid="ct-hda-field-tyGia" value={form.tyGia} onChange={event => setField('tyGia', event.target.value)} /></div>
              <div><label className={df.label}>Mã thuế</label><Input maxLength={10} disabled={readOnly} data-testid="ct-hda-field-maThue" value={form.maThue} onChange={event => setField('maThue', event.target.value)} /></div>
              <div><label className={df.label}>Thuế suất</label><Input inputMode="decimal" disabled={readOnly} data-testid="ct-hda-field-thueSuat" value={form.thueSuat} onChange={event => setField('thueSuat', event.target.value)} /></div>
              <div><label className={df.label}>Tài khoản thuế có</label><Input maxLength={30} disabled={readOnly} data-testid="ct-hda-field-tkThueCo" value={form.tkThueCo} onChange={event => setField('tkThueCo', event.target.value)} /></div>
              <div><label className={df.label}>Tài khoản thuế nợ</label><Input maxLength={30} disabled={readOnly} data-testid="ct-hda-field-tkThueNo" value={form.tkThueNo} onChange={event => setField('tkThueNo', event.target.value)} /></div>
              <Checkbox label="Sửa CK" disabled={readOnly} data-testid="ct-hda-field-suaCk" checked={form.suaCk} onChange={event => setField('suaCk', event.target.checked)} />
              <Checkbox label="Sửa TK thuế" disabled={readOnly} data-testid="ct-hda-field-suaTkThue" checked={form.suaTkThue} onChange={event => setField('suaTkThue', event.target.checked)} />
              <Checkbox label="Sửa thuế" disabled={readOnly} data-testid="ct-hda-field-suaThue" checked={form.suaThue} onChange={event => setField('suaThue', event.target.checked)} />
              <Checkbox label="Sửa thuế CK" disabled={readOnly} data-testid="ct-hda-field-suaThueCk" checked={form.suaThueCk} onChange={event => setField('suaThueCk', event.target.checked)} />
              <div><label className={df.label}>Hạn thanh toán</label><Input inputMode="numeric" disabled={readOnly} data-testid="ct-hda-field-hanTt" value={form.hanTt} onChange={event => setField('hanTt', event.target.value)} /></div>
              <div className={df.spanCol2}><label className={df.label}>Hình thức thanh toán</label><Input maxLength={200} disabled={readOnly} data-testid="ct-hda-field-htTt" value={form.htTt} onChange={event => setField('htTt', event.target.value)} /></div>
            </div>
          </section>
          <section className={df.section}>
            <h2 className={df.sectionTitle}>Thuế GTGT</h2>
            <div className={df.row4}>
              <div><label className={df.label}>Tên hàng thuế</label><Input maxLength={200} disabled={readOnly} data-testid="ct-hda-field-tenVtThue" value={form.tenVtThue} onChange={event => setField('tenVtThue', event.target.value)} /></div>
              <div><label className={df.label}>Tên khách VAT</label><Input maxLength={200} disabled={readOnly} data-testid="ct-hda-field-tenKhVat" value={form.tenKhVat} onChange={event => setField('tenKhVat', event.target.value)} /></div>
              <div className={df.spanCol2}><label className={df.label}>Địa chỉ VAT</label><Input maxLength={200} disabled={readOnly} data-testid="ct-hda-field-diaChiVat" value={form.diaChiVat} onChange={event => setField('diaChiVat', event.target.value)} /></div>
              <div><label className={df.label}>Tiền thuế NT</label><Input inputMode="decimal" disabled={readOnly} data-testid="ct-hda-field-tThueNt" value={form.tThueNt} onChange={event => setField('tThueNt', event.target.value)} /></div>
              <div><label className={df.label}>Tiền thuế</label><Input inputMode="decimal" disabled={readOnly} data-testid="ct-hda-field-tThue" value={form.tThue} onChange={event => setField('tThue', event.target.value)} /></div>
            </div>
          </section>
          <section className={df.section}>
            <h2 className={df.sectionTitle}>Tổng</h2>
            <div className={df.row4}>
              <div><label className={df.label}>Số lượng</label><Input disabled data-testid="ct-hda-field-tSoLuong" value={showMoney(totals.tSoLuong)} /></div>
              <div><label className={df.label}>Tiền bán NT</label><Input disabled data-testid="ct-hda-field-tTienNt2" value={showMoney(totals.tTienNt2)} /></div>
              <div><label className={df.label}>Tiền bán</label><Input disabled data-testid="ct-hda-field-tTien2" value={showMoney(totals.tTien2)} /></div>
              <div><label className={df.label}>Chiết khấu NT</label><Input disabled data-testid="ct-hda-field-tCkNt" value={showMoney(totals.tCkNt)} /></div>
              <div><label className={df.label}>Chiết khấu</label><Input disabled data-testid="ct-hda-field-tCk" value={showMoney(totals.tCk)} /></div>
              <div><label className={df.label}>Tiền vốn NT</label><Input disabled data-testid="ct-hda-field-tTienNt" value={showMoney(totals.tTienNt)} /></div>
              <div><label className={df.label}>Tiền vốn</label><Input disabled data-testid="ct-hda-field-tTien" value={showMoney(totals.tTien)} /></div>
              <div><label className={df.label}>Thanh toán NT</label><Input disabled data-testid="ct-hda-field-tTtNt" value={showMoney(totals.tTtNt)} /></div>
              <div><label className={df.label}>Thanh toán</label><Input disabled data-testid="ct-hda-field-tTt" value={showMoney(totals.tTt)} /></div>
            </div>
          </section>
          <section className={df.section}>
            <h2 className={df.sectionTitle}>Dòng hàng</h2>
            {!readOnly ? (
              <div>
                <Button className={df.btnAddLine} data-testid="ct-hda-line-add-btn" onClick={() => { touch({ ...form, lines: [...form.lines, emptyLine()] }); setSelectedLine(form.lines.length); }}>Thêm dòng</Button>
                <Button className={df.btnDeleteLine} data-testid="ct-hda-line-remove-btn" disabled={selectedLine < 0} onClick={() => { touch({ ...form, lines: form.lines.filter((_, i) => i !== selectedLine) }); setSelectedLine(-1); }}>Xóa dòng</Button>
              </div>
            ) : null}
            <div className={df.tableWrapper}>
              <table className={df.linesTable} data-testid="ct-hda-line-grid">
                <thead>
                  <tr>
                    {['Hàng hoá', 'Tên hàng hoá', 'ĐVT', 'Vị trí', 'Kho', 'Tồn', 'Số lượng', 'Giá bán', 'Thành tiền', '% CK', 'Chiết khấu', 'Chiết khấu', 'TK CK', 'Tk DT', 'Giá VND', 'Tiền VND', 'Giá vốn', 'Tiền vốn', 'Giá vốn', 'TK VT', 'TK GV', 'V.Việc', 'Hợp đồng', 'khoản mục', 'Trung tâm lợi nhuận', 'Trung tâm chi phí', 'Phòng ban'].map((label, headerIndex) => <th key={`${label}-${headerIndex}`}>{label}</th>)}
                  </tr>
                </thead>
                <tbody>
                  {form.lines.map((line, index) => (
                    <tr key={`${line.sttRec0}-${index}`} aria-selected={selectedLine === index} style={selectedLine === index ? { background: 'var(--ds-color-primary-bg, rgba(13, 110, 253, 0.08))' } : undefined} onClick={() => setSelectedLine(index)}>
                      <td><Input disabled={readOnly} data-testid={`ct-hda-line-${index}-maVt`} value={line.maVt} onChange={event => setLine(index, { maVt: event.target.value })} onBlur={() => { void onBlurMaterial(index); }} /></td>
                      <td><Input disabled data-testid={`ct-hda-line-${index}-tenVt`} value={line.tenVt} /></td>
                      <td><Input disabled data-testid={`ct-hda-line-${index}-dvt`} value={line.dvt} /></td>
                      <td><Input disabled={readOnly} data-testid={`ct-hda-line-${index}-maVitri`} value={line.maVitri} onChange={event => setLine(index, { maVitri: event.target.value })} /></td>
                      <td><Input disabled={readOnly} data-testid={`ct-hda-line-${index}-maKhoI`} value={line.maKhoI} onChange={event => setLine(index, { maKhoI: event.target.value })} /></td>
                      <td><Input disabled data-testid={`ct-hda-line-${index}-ton13`} value={line.ton13} /></td>
                      <td><Input inputMode="decimal" disabled={readOnly} data-testid={`ct-hda-line-${index}-soLuong`} value={line.soLuong} onChange={event => setLine(index, { soLuong: event.target.value })} /></td>
                      <td><Input inputMode="decimal" disabled={readOnly} data-testid={`ct-hda-line-${index}-giaNt2`} value={line.giaNt2} onChange={event => setLine(index, { giaNt2: event.target.value })} /></td>
                      <td><Input inputMode="decimal" disabled={readOnly} data-testid={`ct-hda-line-${index}-tienNt2`} value={line.tienNt2} onChange={event => setLine(index, { tienNt2: event.target.value })} /></td>
                      <td><Input inputMode="decimal" disabled={readOnly} data-testid={`ct-hda-line-${index}-ptCk`} value={line.ptCk} onChange={event => setLine(index, { ptCk: event.target.value })} /></td>
                      <td><Input inputMode="decimal" disabled={readOnly} data-testid={`ct-hda-line-${index}-ckNt`} value={line.ckNt} onChange={event => setLine(index, { ckNt: event.target.value })} /></td>
                      <td><Input inputMode="decimal" disabled={readOnly} data-testid={`ct-hda-line-${index}-ck`} value={line.ck} onChange={event => setLine(index, { ck: event.target.value })} /></td>
                      <td><Input disabled={readOnly} data-testid={`ct-hda-line-${index}-tkCk`} value={line.tkCk} onChange={event => setLine(index, { tkCk: event.target.value })} /></td>
                      <td><Input disabled={readOnly} data-testid={`ct-hda-line-${index}-tkDt`} value={line.tkDt} onChange={event => setLine(index, { tkDt: event.target.value })} /></td>
                      <td><Input disabled data-testid={`ct-hda-line-${index}-gia2`} value={showMoney(lineMoney(line, 'gia2'))} /></td>
                      <td><Input disabled data-testid={`ct-hda-line-${index}-tien2`} value={showMoney(lineMoney(line, 'tien2'))} /></td>
                      <td><Input disabled data-testid={`ct-hda-line-${index}-giaNt`} value={line.giaNt} /></td>
                      <td><Input disabled data-testid={`ct-hda-line-${index}-tienNt`} value={line.tienNt} /></td>
                      <td><Input disabled data-testid={`ct-hda-line-${index}-gia`} value={line.gia} /></td>
                      <td><Input disabled={readOnly} data-testid={`ct-hda-line-${index}-tkVt`} value={line.tkVt} onChange={event => setLine(index, { tkVt: event.target.value })} /></td>
                      <td><Input disabled={readOnly} data-testid={`ct-hda-line-${index}-tkGv`} value={line.tkGv} onChange={event => setLine(index, { tkGv: event.target.value })} /></td>
                      <td><Input disabled={readOnly} data-testid={`ct-hda-line-${index}-maVvI`} value={line.maVvI} onChange={event => setLine(index, { maVvI: event.target.value })} /></td>
                      <td><Input disabled={readOnly} data-testid={`ct-hda-line-${index}-maHdI`} value={line.maHdI} onChange={event => setLine(index, { maHdI: event.target.value })} /></td>
                      <td><Input disabled={readOnly} data-testid={`ct-hda-line-${index}-maPhiI`} value={line.maPhiI} onChange={event => setLine(index, { maPhiI: event.target.value })} /></td>
                      <td><Input disabled={readOnly} data-testid={`ct-hda-line-${index}-maTtlnI`} value={line.maTtlnI} onChange={event => setLine(index, { maTtlnI: event.target.value })} /></td>
                      <td><Input disabled={readOnly} data-testid={`ct-hda-line-${index}-maTtcpI`} value={line.maTtcpI} onChange={event => setLine(index, { maTtcpI: event.target.value })} /></td>
                      <td><Input disabled={readOnly} data-testid={`ct-hda-line-${index}-maBpI`} value={line.maBpI} onChange={event => setLine(index, { maBpI: event.target.value })} /></td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </section>
          <div className={df.footer}>
            <span className={df.totalLabel}>Thanh toán</span>
            <span className={df.totalValue}>{showMoney(totals.tTt)}</span>
          </div>
        </>
      ) : null}
    </div>
  );
};

export default HdaFormPage;
